 document.getElementById('page-settings').append(panel);
 fields.forEach(([key,label,type,help])=>{const wrapper=document.createElement('div'),labelEl=document.createElement('label'),input=document.createElement('input'),hint=document.createElement('p');labelEl.htmlFor='pilot-'+key;labelEl.textContent=label;input.id='pilot-'+key;input.name=key;input.type=type;input.autocomplete='off';input.setAttribute('aria-describedby',input.id+'-help');if(type==='number'){input.min=key==='rpo_minutes'?'0':'0.001';input.max='1000000';input.step='any';}else input.maxLength=key.endsWith('_id')?64:120;hint.id=input.id+'-help';hint.textContent=help;wrapper.append(labelEl,input,hint);document.getElementById('pilot-fields').append(wrapper);});
 let dirty=false;
