 const numeric=new Set(fields.slice(5)),panel=document.getElementById('pilot-planner');
 const tools=document.createElement('section');tools.className='pilot-import-tools';tools.innerHTML='<h3>Reopen a saved pilot draft</h3><p>Select a previously exported pilot configuration draft (JSON, up to 64 KiB). Review it before replacing this worksheet. Import does not apply configuration or verify the proposed values.</p><label for="pilot-import-file">Choose pilot draft file</label><input id="pilot-import-file" type="file" accept=".json,application/json"><p id="pilot-import-feedback" role="status" aria-live="polite">No draft selected.</p>';
