  const values={};for(const key of fields){const value=data.values[key];if(value===null){values[key]=null;continue;}if(numeric.has(key)){if(typeof value!=='number'||!Number.isFinite(value)||value>1000000||(key==='rpo_minutes'?value<0:value<=0))throw Error('Invalid numeric target in '+key+'.');values[key]=value;}else{if(typeof value!=='string'||!value.trim()||value!==value.trim()||value.length>(key.endsWith('_id')?64:120)||/[\u0000-\u001f\u007f]/.test(value)||(key.endsWith('_id')&&!/^[A-Za-z0-9_-]{1,64}$/.test(value)))throw Error('Invalid text in '+key+'.');values[key]=value;}}
  return values;
