 async function refresh(){const request=++sequence;rows=[];document.getElementById('svc-rows').replaceChildren();feedback.textContent='Loading current credential metadata…';try{const data=await edgFetch('/api/service-credentials');if(request!==sequence)return;if(data.scope!=='local-synthetic-service-identity'||data.production_ready!==false||!Array.isArray(data.credentials))throw Error('Unsupported credential response');rows=data.credentials;for(const row of rows){const tr=document.createElement('tr');for(const text of [row.label+' · '+row.id,row.device_id+' · '+row.site_id+'/'+row.asset_id+' · revision '+row.binding_revision,row.status,new Date(row.expires_at*1000).toISOString()]){const td=document.createElement('td');td.textContent=text;tr.append(td);}const td=document.createElement('td');if(row.status!=='revoked'){const b=document.createElement('button');b.type='button';b.className='action-outline';b.textContent='Revoke';b.disabled=busy;b.addEventListener('click',()=>{clearSecrets();selected=row;document.getElementById('svc-revoke-form').reset();document.getElementById('svc-revoke-context').textContent=row.label+' · '+row.device_id+' · credential revision '+row.revision+'. Revocation does not remove retained observations.';document.getElementById('svc-revoke-feedback').textContent='';revoke.showModal();document.getElementById('svc-revoke-cancel').focus();});td.append(b);}tr.append(td);document.getElementById('svc-rows').append(tr);}feedback.textContent=rows.length+' retained credentials. Metadata read only; no bearer tokens returned.';}catch(error){if(request===sequence)feedback.textContent=error.status===404?'Service identity backend is not active. Restart the updated local server; no credentials can be issued yet.':'Credential metadata unavailable. Refresh before making changes.';}}
 function setBusy(value){busy=value;panel.querySelectorAll('input,textarea,button').forEach(el=>el.disabled=value);revoke.querySelectorAll('input,textarea,button').forEach(el=>el.disabled=value);}
 document.getElementById('svc-use-binding').addEventListener('click',()=>{if(typeof registryRows==='undefined')return;const chosen=registryRows.find(row=>row.device_id===document.getElementById('registry-example-device')?.value&&row.status==='active');if(!chosen){feedback.textContent='Choose an active synthetic test binding in the existing registry first.';return;}document.getElementById('svc-device').value=chosen.device_id;document.getElementById('svc-binding-revision').value=chosen.revision;feedback.textContent='Selected device and revision copied. No credential issued.';});
 document.getElementById('svc-create-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;clearSecretsForIssue();const epoch=viewEpoch;const body={label:document.getElementById('svc-label').value.trim(),device_id:document.getElementById('svc-device').value.trim(),expected_binding_revision:Number(document.getElementById('svc-binding-revision').value),lifetime_minutes:Number(document.getElementById('svc-lifetime').value),current_password:document.getElementById('svc-password').value,reason:document.getElementById('svc-reason').value.trim()};document.getElementById('svc-password').value='';setBusy(true);try{const data=await edgFetch('/api/service-credentials',mutation(body));if(data.scope!=='local-synthetic-service-identity'||data.production_ready!==false||!/^edgeops_svc_[0-9a-f]{64}$/.test(data.token))throw Error('Unsupported issuance response');if(epoch===viewEpoch&&!document.hidden){document.getElementById('svc-secret').value=data.token;secret.showModal();document.getElementById('svc-secret-close').focus();}await refresh();feedback.textContent='Credential issued. If its one-time response was lost, refresh and revoke the unused credential before retrying.';}catch(error){feedback.textContent='Issuance unconfirmed or refused ('+(error.status||'network')+'). Refresh the list before retrying; no token can be recovered from metadata.';}finally{body.current_password='';document.getElementById('svc-password').value='';setBusy(false);}});
 function clearSecretsForIssue(){document.getElementById('svc-secret').value='';if(secret.open)secret.close();}
 document.getElementById('svc-revoke-form').addEventListener('submit',async event=>{event.preventDefault();if(busy||!selected)return;const row=selected,body={expected_revision:row.revision,current_password:document.getElementById('svc-revoke-password').value,reason:document.getElementById('svc-revoke-reason').value.trim()};document.getElementById('svc-revoke-password').value='';setBusy(true);try{await edgFetch('/api/service-credentials/'+encodeURIComponent(row.id)+'/revoke',mutation(body));revoke.close();selected=null;await refresh();feedback.textContent='Credential revoked. Retained observations unchanged.';}catch(error){document.getElementById('svc-revoke-feedback').textContent='Revocation unconfirmed or refused. Refresh metadata before retrying.';}finally{body.current_password='';document.getElementById('svc-revoke-password').value='';setBusy(false);}});
 document.getElementById('svc-secret-close').addEventListener('click',()=>clearSecrets());secret.addEventListener('close',()=>{document.getElementById('svc-secret').value='';});
 document.getElementById('svc-revoke-cancel').addEventListener('click',()=>revoke.close());revoke.addEventListener('close',()=>{selected=null;document.getElementById('svc-revoke-password').value='';});
 document.getElementById('svc-refresh').addEventListener('click',()=>{clearSecrets();refresh();});
 window.addEventListener('hashchange',()=>{viewEpoch++;clearSecrets();if(revoke.open)revoke.close();});window.addEventListener('pagehide',clearSecrets);document.addEventListener('visibilitychange',()=>{if(document.hidden){viewEpoch++;clearSecrets();}});
 try{const me=await edgFetch('/api/me');if(me.role==='admin'){panel.hidden=false;await refresh();}}catch{}
